    for c in colbands[1:]:
        if c==cur[-1]+1: cur.append(c)
        else: cbands.append(cur); cur=[c]
    cbands.append(cur)
    # find source band pair (rb, cb) containing non-bg cells (values differing from band majority? use any nonzero non-sep cell)
    out=[row[:] for row in g]
    src=None
    for i,rb in enumerate(bands):
        for j,cb in enumerate(cbands):
            if any(g[r][c]!=1 for r in rb for c in cb):
                src=(i,j)
    if src is None: return g
    si,sj=src
    srb, scb = bands[si], cbands[sj]
    for i,rb in enumerate(bands):
        for j,cb in enumerate(cbands):
